import json
bl=np.load('base_logits.npy'); ids=json.load(open('all_ids.json'))
def stress(lg, ks=(1,1.5,2,3)):
    pb=bl.argmax(1); d=lg-bl
    return [int(((bl/k+d).argmax(1)!=pb).sum()) for k in ks]
for p in ['pass_10','pass_11','pass_12','pass_3','pass_27','pass_28']:
    try:
        pr=json.load(open(p+'/predictions.json')); idx={r['id']:i for i,r in enumerate(pr)}
        if len(pr)<1000: print(p,len(pr)); continue
        key='logits_edited' if 'logits_edited' in pr[0] else None
        lg=np.array([pr[idx[i]][key] for i in ids])
        print(p, stress(lg), np.sqrt(((lg-bl)**2).mean()).round(4))
    except Exception as e: print(p,repr(e)[:100])
